"use client";
import {ArtemisScope} from "./artemis-scope";
import View0 from "./components/sidebar/variants/01-rail";
import View1 from "./components/sidebar/variants/02-workspace";
import View2 from "./components/sidebar/variants/03-offcanvas";
const views={"rail":View0,"workspace":View1,"offcanvas":View2};
export interface ArtemisSidebarProps {className?:string;variant?:"rail"|"workspace"|"offcanvas";}
export function ArtemisSidebar({className,variant="rail"}:ArtemisSidebarProps){const View=views[variant];return <ArtemisScope className={className}><View/></ArtemisScope>;}

// @zeus-internal
const GUARD_ATTRIBUTE = "data-radix-focus-guard";
const MARKER_ATTRIBUTE = "data-aria-hidden";
const LOCK_ATTRIBUTE = "data-scroll-locked";
let guardCount = 0;
function createFocusGuard(): HTMLSpanElement {
    const guard = document.createElement("span");
    guard.setAttribute(GUARD_ATTRIBUTE, "");
    guard.tabIndex = 0;
    guard.style.outline = "none";
    guard.style.opacity = "0";
    guard.style.position = "fixed";
    guard.style.pointerEvents = "none";
    return guard;
}
export function acquireFocusGuards(): () => void {
    const existing = document.querySelectorAll(`[${GUARD_ATTRIBUTE}]`);
    document.body.insertAdjacentElement("afterbegin", existing[0] ?? createFocusGuard());
    document.body.insertAdjacentElement("beforeend", existing[1] ?? createFocusGuard());
    guardCount += 1;
    return () => {
        if (guardCount === 1) {
            for (const node of Array.from(document.querySelectorAll(`[${GUARD_ATTRIBUTE}]`)))
                node.remove();
        }
        guardCount -= 1;
    };
}
const hiddenCount = new WeakMap<Element, number>();
const markerCount = new WeakMap<Element, number>();
const alreadyHiddenNodes = new WeakSet<Element>();
export function hideOthers(target: Element): () => void {
    const body = target.ownerDocument.body;
    const targets: Element[] = [target, ...Array.from(body.querySelectorAll("[aria-live], script"))];
    const stop = new Set<Element>(targets);
    const keep = new Set<Node>();
    const keepWithAncestors = (node: Node | null) => {
        if (!node || keep.has(node))
            return;
        keep.add(node);
        keepWithAncestors(node.parentNode);
    };
    for (const node of targets)
        keepWithAncestors(node);
    const hidden: Element[] = [];
    const walk = (parent: Element) => {
        if (stop.has(parent))
            return;
        for (const node of Array.from(parent.children)) {
            if (keep.has(node)) {
                walk(node);
                continue;
            }
            const attribute = node.getAttribute("aria-hidden");
            const wasHidden = attribute !== null && attribute !== "false";
            const count = (hiddenCount.get(node) ?? 0) + 1;
            const markers = (markerCount.get(node) ?? 0) + 1;
            hiddenCount.set(node, count);
            markerCount.set(node, markers);
            hidden.push(node);
            if (count === 1 && wasHidden)
                alreadyHiddenNodes.add(node);
            if (markers === 1)
                node.setAttribute(MARKER_ATTRIBUTE, "true");
            if (!wasHidden)
                node.setAttribute("aria-hidden", "true");
        }
    };
    walk(body);
    return () => {
        for (const node of hidden) {
            const count = (hiddenCount.get(node) ?? 1) - 1;
            const markers = (markerCount.get(node) ?? 1) - 1;
            hiddenCount.set(node, count);
            markerCount.set(node, markers);
            if (count === 0) {
                if (!alreadyHiddenNodes.has(node))
                    node.removeAttribute("aria-hidden");
                alreadyHiddenNodes.delete(node);
            }
            if (markers === 0)
                node.removeAttribute(MARKER_ATTRIBUTE);
        }
    };
}
let lockCount = 0;
let lockStyle: HTMLStyleElement | null = null;
function px(value: string): number {
    const parsed = Number.parseInt(value, 10);
    return Number.isFinite(parsed) ? parsed : 0;
}
function lockCss(): string {
    const computed = window.getComputedStyle(document.body);
    const left = px(computed.marginLeft);
    const top = px(computed.marginTop);
    const right = px(computed.marginRight);
    const gap = Math.max(0, window.innerWidth - document.documentElement.clientWidth + right - left);
    return `
  .with-scroll-bars-hidden {
   overflow: hidden !important;
   padding-right: ${gap}px !important;
  }
  body[${LOCK_ATTRIBUTE}] {
    overflow: hidden !important;
    overscroll-behavior: contain;
    position: relative !important;
    padding-left: ${left}px;
    padding-top: ${top}px;
    padding-right: ${right}px;
    margin-left:0;
    margin-top:0;
    margin-right: ${gap}px !important;
  }
  body[${LOCK_ATTRIBUTE}] {
    --removed-body-scroll-bar-size: ${gap}px;
  }
`;
}
export function lockBodyScroll(): () => void {
    if (lockCount === 0) {
        lockStyle = document.createElement("style");
        lockStyle.textContent = lockCss();
        document.head.appendChild(lockStyle);
    }
    lockCount += 1;
    document.body.setAttribute(LOCK_ATTRIBUTE, String(lockCount));
    return () => {
        lockCount -= 1;
        if (lockCount > 0) {
            document.body.setAttribute(LOCK_ATTRIBUTE, String(lockCount));
            return;
        }
        document.body.removeAttribute(LOCK_ATTRIBUTE);
        lockStyle?.remove();
        lockStyle = null;
    };
}

"use client";
import {useArtemisContainerMobile} from "../../../lib/use-container-mobile";
// @zeus-internal
import { useEffect, useId, useRef, useState, type CSSProperties, type FocusEvent, type KeyboardEvent as ReactKeyboardEvent } from "react";
import { flushSync } from "react-dom";
import { artemisCreatePortal } from "../../../artemis-scope";
import { motion } from "motion/react";
import { House, Layers2, RotateCcwClock, Settings2 } from "lucide-react";
import { ArtemisMorphicTooltip, ArtemisMorphicTooltipProvider } from "./01-rail/morphic-tooltip";
import { ARTEMIS_EASE_DRAWER, ARTEMIS_SPRING_PRESS } from "../../../lib/ease";
import { navigation, type Area } from "./01-rail/data";
import { RailPanel } from "./01-rail/panel";
const areaNames: Area[] = ["Workspace", "Library", "Activity", "Settings"];
const railButton = "art:inline-flex art:items-center art:justify-center art:font-medium art:select-none art:transition-colors art:disabled:pointer-events-none art:disabled:opacity-50 art:hover:bg-primary/5 art:hover:text-foreground art:focus-visible:outline-none art:focus-visible:ring-offset-2 art:focus-visible:ring-offset-background art:size-9 art:outline-none art:focus-visible:ring-2 art:focus-visible:ring-ring art:rounded-full";
const drawerTransition = { duration: 0.36, ease: ARTEMIS_EASE_DRAWER } as const;
const widthTransition = { type: "spring", stiffness: 550, damping: 50, mass: 1 } as const;
const PEEK_CLOSE_DELAY = 140;
function AreaIcon({ area }: {
    area: Area;
}) {
    const props = { size: 24, strokeWidth: 1.7, className: "art:size-5", "aria-hidden": true as const };
    if (area === "Workspace")
        return <House {...props}/>;
    if (area === "Library")
        return <Layers2 {...props}/>;
    if (area === "Activity")
        return <RotateCcwClock {...props}/>;
    return <Settings2 {...props}/>;
}
export default function SidebarRail() {
    const sidebarId = useId();
    const triggerRef = useRef<HTMLButtonElement>(null);
    const [containerRef,mobile] = useArtemisContainerMobile();
    useEffect(() => { if (!mobile) setMobileOpen(false); }, [mobile]);
    const [mobileOpen, setMobileOpen] = useState(false);
    const [drawerVisible, setDrawerVisible] = useState(false);
    const [expanded, setExpanded] = useState(true);
    const [peeking, setPeeking] = useState(false);
    const peekCloseRef = useRef<number | undefined>(undefined);
    const peekingRef = useRef(false);
    const [area, setArea] = useState<Area>("Workspace");
    const [selected, setSelected] = useState("Launch direction");
    useEffect(() => {
        if (!mobileOpen)
            return;
        const focus = window.setTimeout(() => document.querySelector<HTMLButtonElement>("[role=\"dialog\"] button[aria-label=\"Search navigation\"]")?.focus(), 0);
        const onKey = (event: KeyboardEvent) => { if (event.key === "Escape") {
            event.preventDefault();
            closeMobile();
        } };
        window.addEventListener("keydown", onKey);
        return () => { window.clearTimeout(focus); window.removeEventListener("keydown", onKey); };
    }, [mobileOpen]);
    useEffect(() => {
        const onShortcut = (event: KeyboardEvent) => {
            if (event.key.toLowerCase() !== "b" || !(event.ctrlKey || event.metaKey))
                return;
            event.preventDefault();
            if (mobile) {
                setMobileOpen(open => !open);
                return;
            }
            flushSync(() => { if (peekingRef.current)
                setPeeking(false);
            else
                setExpanded(open => !open); peekingRef.current = false; });
            triggerRef.current?.focus();
        };
        window.addEventListener("keydown", onShortcut);
        return () => window.removeEventListener("keydown", onShortcut);
    }, [mobile]);
    useEffect(() => { peekingRef.current = peeking; }, [peeking]);
    useEffect(() => () => window.clearTimeout(peekCloseRef.current), []);
    useEffect(() => {
        if (mobileOpen) {
            setDrawerVisible(true);
            return;
        }
        const timer = window.setTimeout(() => setDrawerVisible(false), 360);
        return () => window.clearTimeout(timer);
    }, [mobileOpen]);
    const closeMobile = () => { setMobileOpen(false); triggerRef.current?.focus(); };
    const selectArea = (next: Area) => {
        if (next !== area) {
            setArea(next);
            setSelected(navigation[next][0].pages[0].title);
        }
        if (mobile)
            setMobileOpen(true);
        else if (!expanded) {
            setExpanded(true);
            setPeeking(false);
        }
    };
    const closePeek = () => { cancelPeekClose(); setPeeking(false); };
    const dismissPeek = () => { if (!peeking)
        return; closePeek(); triggerRef.current?.focus(); };
    const selectPage = (page: string) => { setSelected(page); dismissPeek(); };
    const newPage = () => { setSelected("Untitled page"); if (mobile)
        closeMobile();
    else
        dismissPeek(); };
    const togglePanel = () => { if (mobile)
        setMobileOpen(open => !open);
    else {
        setExpanded(open => !open);
        setPeeking(false);
    } };
    const railState = expanded ? "expanded" : "collapsed";
    const cancelPeekClose = () => window.clearTimeout(peekCloseRef.current);
    const startPeek = () => { cancelPeekClose(); if (!expanded && !mobile)
        setPeeking(true); };
    const endPeek = () => { cancelPeekClose(); peekCloseRef.current = window.setTimeout(() => setPeeking(false), PEEK_CLOSE_DELAY); };
    const onRailFocus = () => startPeek();
    const onRailBlur = (event: FocusEvent<HTMLDivElement>) => { if (!event.currentTarget.contains(event.relatedTarget as Node | null))
        closePeek(); };
    const onRailKeyDown = (event: ReactKeyboardEvent<HTMLDivElement>) => { if (event.key === "Escape" && peeking) {
        event.preventDefault();
        dismissPeek();
    } };
    return <ArtemisMorphicTooltipProvider>
    <>
      <div ref={containerRef} data-slot="sidebar-wrapper" data-state={railState} style={{ "--artemis-sidebar-width": "17rem", "--artemis-sidebar-width-icon": "4.25rem", "--artemis-sidebar-width-mobile": "19rem" } as CSSProperties} className="art:group/sidebar-wrapper art:flex art:w-full art:min-w-0 art:relative art:h-[720px] art:min-h-0 art:overflow-hidden art:rounded-2xl art:border art:border-border art:bg-background">
        <motion.div data-rail-state={railState} data-peeking={peeking} className="art:relative art:z-20 art:h-full art:shrink-0 art:@max-[768px]/artemis:w-16!" initial={false} animate={{ width: expanded ? "21.5rem" : "4rem" }} transition={widthTransition} onMouseEnter={cancelPeekClose} onMouseLeave={endPeek} onFocus={onRailFocus} onBlur={onRailBlur} onKeyDown={onRailKeyDown}>
          <nav aria-label="Workspace areas" className="art:relative art:z-30 art:flex art:h-full art:w-16 art:flex-col art:items-center art:gap-4 art:bg-background art:py-4" onMouseEnter={startPeek}>
            {areaNames.map(name => <ArtemisMorphicTooltip key={name} content={name} side="right"><motion.button type="button" className={`${railButton} ${area === name ? "art:bg-muted art:text-foreground" : "art:text-muted-foreground"}`} aria-label={name} aria-current={area === name ? "page" : undefined} aria-controls={sidebarId} aria-expanded={area === name && (mobile ? mobileOpen : expanded)} tabIndex={0} whileHover={{ scale: 1.01 }} whileTap={{ scale: 0.99 }} transition={ARTEMIS_SPRING_PRESS} onClick={() => selectArea(name)}><AreaIcon area={name}/></motion.button></ArtemisMorphicTooltip>)}
            <div data-slot="sidebar-rail-footer" className="art:mt-auto"><ArtemisMorphicTooltip content="Casey Shaw" side="right"><motion.button type="button" className="art:inline-flex art:items-center art:justify-center art:font-medium art:select-none art:transition-colors art:disabled:pointer-events-none art:disabled:opacity-50 art:hover:bg-primary/5 art:hover:text-foreground art:focus-visible:outline-none art:focus-visible:ring-offset-2 art:focus-visible:ring-offset-background art:size-9 art:outline-none art:focus-visible:ring-2 art:focus-visible:ring-ring art:border art:border-border art:text-xs art:text-foreground art:rounded-full" aria-label="Account: Casey Shaw" tabIndex={0} whileHover={{ scale: 1.01 }} whileTap={{ scale: 0.99 }} transition={ARTEMIS_SPRING_PRESS}>CS</motion.button></ArtemisMorphicTooltip></div>
          </nav>
          <motion.aside id={sidebarId} aria-label="Canvas navigation" aria-hidden={!expanded && !peeking ? true : undefined} inert={!expanded && !peeking ? true : undefined} data-slot="sidebar" data-state={expanded || peeking ? "expanded" : "collapsed"} data-collapsible="offcanvas" data-variant="sidebar" data-side="left" className="art:group/sidebar art:relative art:hidden art:h-auto art:shrink-0 art:@min-[768px]/artemis:block art:will-change-[width] art:peer art:w-76 art:rounded-2xl art:border art:border-border art:bg-background art:shadow-none art:@min-[768px]/artemis:absolute art:@min-[768px]/artemis:inset-y-2 art:@min-[768px]/artemis:left-16 art:@min-[768px]/artemis:w-auto art:@min-[768px]/artemis:border-0" initial={false} animate={{ width: expanded || peeking ? "var(--artemis-sidebar-width)" : "0rem" }} transition={widthTransition}>
            <motion.div className={`art:top-0 art:flex art:flex-col art:overflow-hidden art:w-[var(--artemis-sidebar-width)] art:static art:h-full art:rounded-2xl art:border art:border-border art:shadow-none ${expanded ? "art:bg-background" : "art:bg-popover"}`} initial={false} animate={{ opacity: expanded || peeking ? 1 : 0, x: expanded || peeking ? "0%" : "-100%" }} transition={drawerTransition}>
              <RailPanel area={area} selected={selected} pinned={expanded} mobile={false} onCollapse={togglePanel} onMobileClose={closeMobile} onNewPage={newPage} onSelect={selectPage}/>
            </motion.div>
          </motion.aside>
        </motion.div>
        <div className="art:relative art:flex art:min-w-0 art:flex-1 art:flex-col">
          <header className="art:flex art:h-16 art:shrink-0 art:items-center art:gap-3 art:px-4 art:@min-[640px]/artemis:px-6">
            <ArtemisMorphicTooltip content={mobile || !expanded ? "Expand navigation" : "Collapse navigation"} side="bottom"><motion.button ref={triggerRef} type="button" className="art:inline-flex art:items-center art:justify-center art:font-medium art:select-none art:transition-colors art:disabled:pointer-events-none art:disabled:opacity-50 art:text-muted-foreground art:hover:bg-primary/5 art:hover:text-foreground art:focus-visible:outline-none art:focus-visible:ring-offset-2 art:focus-visible:ring-offset-background art:size-9 art:outline-none art:focus-visible:ring-2 art:focus-visible:ring-ring art:rounded-full" aria-label={mobile || !expanded ? "Expand navigation" : "Collapse navigation"} aria-controls={sidebarId} aria-expanded={mobile ? mobileOpen : expanded} tabIndex={0} whileHover={{ scale: 1.01 }} whileTap={{ scale: 0.99 }} transition={ARTEMIS_SPRING_PRESS} onClick={togglePanel}><svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className="art:lucide art:lucide-panel-left art:size-4" aria-hidden="true"><rect width="18" height="18" x="3" y="3" rx="2"/><path d="M9 3v18"/></svg></motion.button></ArtemisMorphicTooltip>
            <div data-slot="sidebar-rail-workspace-header" className="art:flex art:min-w-0 art:flex-1 art:items-center art:gap-3"><p className="art:truncate art:text-sm art:font-medium">{selected}</p></div>
          </header>
          <div className="art:min-h-0 art:flex-1 art:overflow-auto art:p-4 art:pt-6 art:@min-[640px]/artemis:p-8 art:@min-[640px]/artemis:pt-8"><div className="art:mx-auto art:flex art:h-full art:max-w-xl art:flex-col art:justify-center art:pb-12">
            <div className="art:mb-6 art:flex art:items-center art:gap-2 art:text-xs art:text-muted-foreground"><svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className="art:lucide art:lucide-file-text art:size-4" aria-hidden="true"><path d="M6 22a2 2 0 0 1-2-2V4a2 2 0 0 1 2-2h8a2.4 2.4 0 0 1 1.704.706l3.588 3.588A2.4 2.4 0 0 1 20 8v12a2 2 0 0 1-2 2z"/><path d="M14 2v5a1 1 0 0 0 1 1h5"/><path d="M10 9H8"/><path d="M16 13H8"/><path d="M16 17H8"/></svg>Private page</div>
            <h1 className="art:text-4xl art:font-medium art:tracking-tight">{selected}</h1>
            <p className="art:mt-4 art:max-w-md art:text-sm art:leading-6 art:text-muted-foreground">A place for the early thoughts, useful references, and small decisions that move the work forward.</p>
            <div className="art:mt-9 art:divide-y art:divide-border art:rounded-2xl art:border art:border-border art:bg-background art:px-5">
              <div className="art:flex art:gap-4 art:py-5"><span className="art:pt-0.5 art:font-mono art:text-xs art:text-muted-foreground">01</span><div><p className="art:text-sm art:font-medium">Find the starting point</p><p className="art:mt-1 art:text-xs art:leading-5 art:text-muted-foreground">Bring the notes and references together.</p></div></div>
              <div className="art:flex art:gap-4 art:py-5"><span className="art:pt-0.5 art:font-mono art:text-xs art:text-muted-foreground">02</span><div><p className="art:text-sm art:font-medium">Make room for the good ideas</p><p className="art:mt-1 art:text-xs art:leading-5 art:text-muted-foreground">Keep the next step clear and close.</p></div></div>
              <div className="art:flex art:gap-4 art:py-5"><span className="art:pt-0.5 art:font-mono art:text-xs art:text-muted-foreground">03</span><div><p className="art:text-sm art:font-medium">Share when it feels ready</p><p className="art:mt-1 art:text-xs art:leading-5 art:text-muted-foreground">A little progress is still progress.</p></div></div>
            </div>
          </div></div>
        </div>
      </div>
    </>
    {mobile && typeof document !== "undefined" && artemisCreatePortal(<div className={`art:pointer-events-none art:fixed art:left-0 art:top-0 art:z-50 art:size-0 art:@min-[768px]/artemis:hidden ${drawerVisible ? "art:visible" : "art:invisible"}`}>
      <motion.button type="button" aria-label="Close sidebar" tabIndex={mobileOpen ? 0 : -1} className={`art:fixed art:inset-0 art:bg-black/40 ${mobileOpen ? "art:pointer-events-auto" : "art:pointer-events-none"}`} initial={false} animate={{ opacity: mobileOpen ? 1 : 0 }} transition={drawerTransition} onClick={closeMobile}/>
      <motion.div role="dialog" aria-modal="true" aria-label="Canvas navigation" aria-hidden={!mobileOpen} inert={!mobileOpen ? true : undefined} tabIndex={-1} data-mobile="true" data-state={mobileOpen ? "expanded" : "collapsed"} data-side="left" className={`art:fixed art:inset-y-0 art:flex art:h-dvh art:max-w-[88vw] art:flex-col art:overflow-hidden art:will-change-transform art:left-0 ${mobileOpen ? "art:pointer-events-auto" : "art:pointer-events-none"} art:w-76 art:rounded-2xl art:border art:border-border art:bg-background art:shadow-none art:@min-[768px]/artemis:absolute art:@min-[768px]/artemis:inset-y-2 art:@min-[768px]/artemis:left-16 art:@min-[768px]/artemis:w-auto art:@min-[768px]/artemis:border-0`} style={{ opacity: 1 }} initial={false} animate={{ x: mobileOpen ? "0%" : "-100%" }} transition={drawerTransition}>
        <RailPanel area={area} selected={selected} pinned={expanded} mobile onCollapse={togglePanel} onMobileClose={closeMobile} onNewPage={newPage} onSelect={selectPage}/>
      </motion.div>
    </div>, document.body)}
  </ArtemisMorphicTooltipProvider>;
}

// @zeus-internal
export type Area = "Workspace" | "Library" | "Activity" | "Settings";
export type Page = {
    title: string;
    icon?: "folder" | "book" | "file" | "clock" | "settings" | "house" | "layers";
};
export type Group = {
    label: string;
    pages: readonly Page[];
};
export const navigation: Record<Area, readonly Group[]> = {
    Workspace: [
        { label: "Pinned", pages: [{ title: "Brand notes", icon: "folder" }, { title: "Website refresh", icon: "folder" }] },
        { label: "Projects", pages: [{ title: "Field studies", icon: "folder" }] },
        { label: "Recent", pages: [{ title: "Launch direction" }, { title: "Research notes" }, { title: "Campaign outline" }, { title: "A few good ideas" }, { title: "Onboarding checklist" }, { title: "Friday recap" }] },
    ],
    Library: [{ label: "Collections", pages: [{ title: "References", icon: "book" }, { title: "Saved pages", icon: "file" }, { title: "Assets", icon: "folder" }] }],
    Activity: [{ label: "Updates", pages: [{ title: "This week", icon: "clock" }, { title: "Shared with you", icon: "file" }, { title: "Archive", icon: "folder" }] }],
    Settings: [{ label: "Workspace", pages: [{ title: "Preferences", icon: "settings" }, { title: "Members", icon: "house" }, { title: "Connections", icon: "layers" }] }],
};

"use client";
// @zeus-internal
import { animate, motion, type Transition, useMotionValue, useReducedMotion } from "motion/react";
import { createContext, type FocusEvent, type PointerEvent, type ReactNode, useCallback, useContext, useEffect, useId, useLayoutEffect, useMemo, useRef, useState, } from "react";
import { artemisCreatePortal } from "../../../../artemis-scope";
import { ARTEMIS_EASE_OUT } from "../../../../lib/ease";
export type TooltipSide = "top" | "bottom" | "right";
const CLOSE_DELAY = 80;
const WARM_WINDOW = 230;
const GAP = 10;
const EDGE = 12;
const INSTANT: Transition = { duration: 0 };
const WRAPPER_TRANSITION: Transition = { duration: 0.15, ease: ARTEMIS_EASE_OUT };
const LABEL_TRANSITION: Transition = {
    opacity: { duration: 0.14, ease: ARTEMIS_EASE_OUT },
    y: { type: "spring", duration: 0.42, bounce: 0.18 },
};
const MORPH_SPRING: Transition = { type: "spring", stiffness: 215, damping: 25, mass: 1.2, restDelta: 0.001 };
const SIZE_SPRING: Transition = { type: "spring", stiffness: 158, damping: 18, mass: 1, restDelta: 0.001 };
type Size = {
    width: number;
    height: number;
};
type Rect = {
    left: number;
    top: number;
    width: number;
    height: number;
};
const ESTIMATED_SIZE: Size = { width: 90, height: 30 };
type Arrival = "fresh" | "jump" | "morph";
type Tip = {
    id: string;
    content: ReactNode;
    anchor: HTMLElement;
    rect: Rect;
    instant: boolean;
    arrival: Arrival;
    seq: number;
    labelKey: number;
    side: TooltipSide;
};
type TooltipApi = {
    enter: (id: string, content: ReactNode, el: HTMLElement, side: TooltipSide) => void;
    focus: (id: string, content: ReactNode, el: HTMLElement, side: TooltipSide) => void;
    hide: (id: string) => void;
    update: (id: string, content: ReactNode) => void;
};
const TooltipContext = createContext<TooltipApi | null>(null);
function rectOf(el: HTMLElement): Rect {
    const r = el.getBoundingClientRect();
    return { left: r.left, top: r.top, width: r.width, height: r.height };
}
export function ArtemisMorphicTooltipProvider({ children, delay = 90 }: {
    children: ReactNode;
    delay?: number;
}) {
    const reduce = useReducedMotion() === true;
    const [tip, setTip] = useState<Tip | null>(null);
    const [open, setOpen] = useState(false);
