/** Track translation as well as resize while an anchored layer is mounted. */
export function observeAnchor(element: HTMLElement, onMove: () => void): () => void {
  let previous = "", disposed = false, frame = 0;
  const measure = () => {
    if (disposed) return;
    const box = element.getBoundingClientRect();
    const current = [box.left, box.top, box.width, box.height].join("/");
